"use client";

// Fläche anlegen oder bearbeiten – inkl. Flurstücken. Speichern als Entwurf oder direkt einreichen.

import { useId, useState } from "react";
import { useRouter } from "next/navigation";
import { Plus, Trash2 } from "lucide-react";
import Button from "@/components/ui/Button";
import { senden } from "@/lib/plattform/client";
import { BUNDESLAENDER, FLAECHE_NUTZUNG, LAENDER } from "@/lib/plattform/konstanten";
import { FREIFLAECHE } from "@/lib/invest/markt";
import { eingabe, textbereich, auswahlfeld, Feld, FehlerBox } from "./felder";
import { FeldFehler, fehlerText, regeln, useFeldPruefung } from "./Bedienung/pruefung";

// Inline-Validierung (Bedienung & Onboarding): verständliche Meldungen direkt am Feld
const PRUEFUNG = {
  bezeichnung: [regeln.pflicht("Bitte geben Sie der Fläche einen Namen, z. B. „Acker am Mühlweg“."), regeln.laenge(3, 120, "Die Bezeichnung")],
  plz: [regeln.pflicht("Bitte die Postleitzahl angeben – wir brauchen sie für die Vorprüfung."), (v, alle) => regeln.plz(alle?.land)(v)],
  ort: [regeln.pflicht("Bitte Ort oder Gemeinde angeben.")],
  ha: [regeln.pflicht("Bitte eine ungefähre Größe angeben – eine Schätzung genügt."), regeln.zahl({ min: 0.01, max: 100000, einheit: "ha", was: "Die Größe" })],
};

export default function FlaecheFormular({ flaeche, agriStandard = false }) {
  const router = useRouter();
  const id = useId();
  const neu = !flaeche;
  const [f, setF] = useState(() => ({
    bezeichnung: flaeche?.bezeichnung || "",
    land: flaeche?.land || "DE",
    bundesland: flaeche?.bundesland || "",
    plz: flaeche?.plz || "",
    ort: flaeche?.ort || "",
    ha: flaeche?.ha ?? "",
    nutzung: flaeche?.nutzung || "acker",
    agri: flaeche?.agri ?? agriStandard,
    eigentum: flaeche?.eigentum || "eigentum",
    gemarkung: flaeche?.gemarkung || "",
    flurstuecke: flaeche?.flurstuecke?.length ? flaeche.flurstuecke : [{ gemarkung: "", flur: "", nummer: "" }],
    hinweise: flaeche?.hinweise || "",
  }));
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  const pruef = useFeldPruefung(PRUEFUNG);

  const setze = (k, v) => {
    const neu = { ...f, [k]: v };
    setF(neu);
    pruef.aendern(k, neu);
  };
  const setzeFlurstueck = (i, k, v) => setF((x) => ({ ...x, flurstuecke: x.flurstuecke.map((s, j) => (j === i ? { ...s, [k]: v } : s)) }));

  async function speichern(einreichen) {
    // Einreichen braucht alle Pflichtangaben, ein Entwurf nur die Bezeichnung
    if (einreichen ? !pruef.alles(f) : !pruef.pruefe("bezeichnung", f)) {
      setFehler(einreichen ? "Bitte ergänzen Sie die markierten Angaben – dann können wir die Fläche prüfen." : "");
      return;
    }
    setLaeuft(true);
    setFehler("");
    try {
      const daten = { ...f, flurstuecke: f.flurstuecke.filter((s) => s.nummer || s.gemarkung) };
      if (neu) {
        const r = await senden("/api/portal/flaechen", { body: { ...daten, einreichen } });
        router.push(`/portal/flaechen/${r.flaeche.id}`);
      } else {
        await senden(`/api/portal/flaechen/${flaeche.id}`, { method: "PATCH", body: daten });
        if (einreichen && flaeche.status === "entwurf") await senden("/api/portal/status", { body: { art: "flaeche", id: flaeche.id, nach: "eingegangen" } });
        router.refresh();
      }
    } catch (e) {
      setFehler(fehlerText(e));
    } finally {
      setLaeuft(false);
    }
  }

  const klein = Number(String(f.ha).replace(",", ".")) > 0 && Number(String(f.ha).replace(",", ".")) < FREIFLAECHE.mindestHa && !f.agri;

  return (
    <form
      noValidate
      onSubmit={(e) => {
        e.preventDefault();
        speichern(true);
      }}
      className="space-y-6"
    >
      <fieldset className="grid gap-4 sm:grid-cols-2">
        <legend className="mb-3 font-display text-[16px] font-bold text-ink-900">Lage & Größe</legend>
        <Feld id={`${id}-b`} label="Bezeichnung" pflicht className="sm:col-span-2" hinweis="z. B. „Acker am Mühlweg“ – nur für Sie und uns sichtbar">
          <input id={`${id}-b`} required maxLength={120} className={eingabe} value={f.bezeichnung} onChange={(e) => setze("bezeichnung", e.target.value)} {...pruef.feldProps("bezeichnung", `${id}-b`, f)} />
          <FeldFehler id={`${id}-b`} text={pruef.fehler.bezeichnung} />
        </Feld>
        <Feld id={`${id}-l`} label="Land" pflicht>
          <select id={`${id}-l`} className={auswahlfeld} value={f.land} onChange={(e) => { const neu = { ...f, land: e.target.value, bundesland: "" }; setF(neu); pruef.aendern("plz", neu); }}>
            {Object.entries(LAENDER).map(([k, v]) => (
              <option key={k} value={k}>{v}</option>
            ))}
          </select>
        </Feld>
        <Feld id={`${id}-bl`} label={f.land === "CH" ? "Kanton" : "Bundesland"}>
          <select id={`${id}-bl`} className={auswahlfeld} value={f.bundesland} onChange={(e) => setze("bundesland", e.target.value)}>
            <option value="">Bitte wählen</option>
            {BUNDESLAENDER[f.land].map((b) => (
              <option key={b} value={b}>{b}</option>
            ))}
          </select>
        </Feld>
        <Feld id={`${id}-p`} label="PLZ" pflicht>
          <input id={`${id}-p`} inputMode="numeric" autoComplete="postal-code" required maxLength={10} className={eingabe} value={f.plz} onChange={(e) => setze("plz", e.target.value)} {...pruef.feldProps("plz", `${id}-p`, f)} />
          <FeldFehler id={`${id}-p`} text={pruef.fehler.plz} />
        </Feld>
        <Feld id={`${id}-o`} label="Ort / Gemeinde" pflicht>
          <input id={`${id}-o`} required maxLength={80} className={eingabe} value={f.ort} onChange={(e) => setze("ort", e.target.value)} {...pruef.feldProps("ort", `${id}-o`, f)} />
          <FeldFehler id={`${id}-o`} text={pruef.fehler.ort} />
        </Feld>
        <Feld id={`${id}-h`} label="Größe in Hektar" pflicht hinweis={klein ? `Für Freiflächen-PV sind in der Regel mindestens ${FREIFLAECHE.mindestHa} ha sinnvoll – mehrere Flächen lassen sich bündeln.` : "Grobe Angabe genügt"}>
          <input id={`${id}-h`} inputMode="decimal" required className={eingabe} value={f.ha} onChange={(e) => setze("ha", e.target.value)} {...pruef.feldProps("ha", `${id}-h`, f)} />
          <FeldFehler id={`${id}-h`} text={pruef.fehler.ha} />
        </Feld>
        <Feld id={`${id}-n`} label="Aktuelle Nutzung">
          <select id={`${id}-n`} className={auswahlfeld} value={f.nutzung} onChange={(e) => setze("nutzung", e.target.value)}>
            {Object.entries(FLAECHE_NUTZUNG).map(([k, v]) => (
              <option key={k} value={k}>{v}</option>
            ))}
          </select>
        </Feld>
        <Feld id={`${id}-e`} label="Eigentumsverhältnis">
          <select id={`${id}-e`} className={auswahlfeld} value={f.eigentum} onChange={(e) => setze("eigentum", e.target.value)}>
            <option value="eigentum">Alleineigentum</option>
            <option value="miteigentum">Miteigentum / Erbengemeinschaft</option>
            <option value="verwaltung">Verwaltung für Eigentümer</option>
          </select>
        </Feld>
        <label className="flex items-start gap-3 self-end rounded-xl bg-sand-50 px-4 py-3 text-[14px] text-ink-700 ring-1 ring-inset ring-ink-200">
          <input type="checkbox" checked={f.agri} onChange={(e) => setze("agri", e.target.checked)} className="mt-0.5 h-4 w-4 accent-[#558227]" />
          <span>Landwirtschaftliche Nutzung soll bleiben (Agri-PV)</span>
        </label>
      </fieldset>

      <fieldset>
        <legend className="mb-1 font-display text-[16px] font-bold text-ink-900">Flurstücke</legend>
        <p className="mb-3 text-[13.5px] text-ink-500">Optional, beschleunigt aber die Vorprüfung. Angaben finden Sie im Grundbuchauszug bzw. Katasterplan.</p>
        <div className="space-y-2">
          {f.flurstuecke.map((s, i) => (
            <div key={i} className="grid grid-cols-[1fr_1fr] gap-2 sm:grid-cols-[2fr_1fr_1fr_auto]">
              <input aria-label={`Gemarkung Flurstück ${i + 1}`} placeholder="Gemarkung / KG" className={`${eingabe} col-span-2 sm:col-span-1`} value={s.gemarkung} onChange={(e) => setzeFlurstueck(i, "gemarkung", e.target.value)} />
              <input aria-label={`Flur ${i + 1}`} placeholder="Flur" className={eingabe} value={s.flur} onChange={(e) => setzeFlurstueck(i, "flur", e.target.value)} />
              <input aria-label={`Flurstücksnummer ${i + 1}`} placeholder="Nr." className={eingabe} value={s.nummer} onChange={(e) => setzeFlurstueck(i, "nummer", e.target.value)} />
              <button
                type="button"
                onClick={() => setF((x) => ({ ...x, flurstuecke: x.flurstuecke.length > 1 ? x.flurstuecke.filter((_, j) => j !== i) : [{ gemarkung: "", flur: "", nummer: "" }] }))}
                className="col-span-2 flex h-12 items-center justify-center rounded-xl text-ink-500 ring-1 ring-inset ring-ink-200 hover:bg-ink-50 hover:text-ink-800 sm:col-span-1 sm:w-12"
                aria-label={`Flurstück ${i + 1} entfernen`}
              >
                <Trash2 aria-hidden="true" className="h-4 w-4" />
              </button>
            </div>
          ))}
        </div>
        {f.flurstuecke.length < 50 && (
          <button type="button" onClick={() => setF((x) => ({ ...x, flurstuecke: [...x.flurstuecke, { gemarkung: x.flurstuecke.at(-1)?.gemarkung || "", flur: "", nummer: "" }] }))} className="mt-3 inline-flex items-center gap-1.5 text-[14px] font-semibold text-ov-700 hover:text-ov-800">
            <Plus aria-hidden="true" className="h-4 w-4" /> Flurstück hinzufügen
          </button>
        )}
      </fieldset>

      <Feld id={`${id}-hi`} label="Hinweise" hinweis="z. B. Hofstelle, Leitungen, Wege, Pachtverhältnisse, Wünsche">
        <textarea id={`${id}-hi`} rows={4} maxLength={3000} className={textbereich} value={f.hinweise} onChange={(e) => setze("hinweise", e.target.value)} />
      </Feld>

      <FehlerBox>{fehler}</FehlerBox>
      <div className="flex flex-col gap-3 sm:flex-row">
        {(neu || flaeche.status === "entwurf") && (
          <Button type="submit" disabled={laeuft} pfeil>
            {laeuft ? "Wird gespeichert …" : "Speichern & zur Prüfung einreichen"}
          </Button>
        )}
        <Button variant={neu || flaeche.status === "entwurf" ? "secondary" : "primary"} disabled={laeuft} onClick={() => speichern(false)}>
          {neu ? "Als Entwurf speichern" : "Änderungen speichern"}
        </Button>
      </div>
    </form>
  );
}
import Link from "next/link";
import Begriff from "@/components/Portal/Bedienung/Begriff";
import { FileSignature, MessageSquareText } from "lucide-react";
import FlaecheFormular from "@/components/Portal/FlaecheFormular";
import Checkliste from "@/components/Portal/Checkliste";
import { AktivitaetsFeed, AufgabenKarte } from "@/components/Portal/ObjektBackoffice";
import StatusAktionen from "@/components/Portal/StatusAktionen";
import NachrichtenThread from "@/components/Portal/NachrichtenThread";
import KiFlaeche from "@/components/Portal/Ki/KiFlaeche";
import Zuweisung from "@/components/Portal/Zuweisung";
import { DokumentListe, DokumentUpload } from "@/components/Portal/Dokumente";
import { Angaben, Hinweis, Karte, SeitenKopf, StatusBadge, Stepper, Timeline } from "@/components/Portal/ui";
import { portalNutzer, laden, istAdmin } from "@/lib/plattform/server/seite";
import { backend } from "@/lib/plattform/backend";
import { FLAECHE_NUTZUNG, LAENDER } from "@/lib/plattform/konstanten";
import { statusInfo } from "@/lib/plattform/prozesse";
import { datum, datumZeit, eur, ha } from "@/lib/plattform/format";
import { PACHT } from "@/lib/invest/markt";

export const metadata = { title: "Fläche" };

export default async function Flaeche({ params }) {
  const { id } = await params;
  const n = await portalNutzer();
  const b = backend();
  const f = await laden(() => b.flaeche(n, id));
  const admin = istAdmin(n);
  const eigen = f.nutzerId === n.id || f.meinZugriff === "schreiben"; // Team: Teamrolle ≥ Mitglied bearbeitet wie der Eigentümer
  const [thread, dokumente, adminKonten] = await Promise.all([
    b.nachrichten(n, "flaeche", id),
    b.dokumente(n, { bezugArt: "flaeche", bezugId: id }),
    admin ? b.adminKonten(n) : [],
  ]);
  const bearbeitbar = admin || (eigen && ["entwurf", "eingegangen"].includes(f.status));
  const pa = f.pachtangebot;

  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow={admin && !eigen ? "Fläche · Backoffice" : "Fläche"}
        titel={f.bezeichnung}
        text={[ha(f.ha), FLAECHE_NUTZUNG[f.nutzung], [f.plz, f.ort].filter(Boolean).join(" "), LAENDER[f.land]].filter(Boolean).join(" · ")}
        aktionen={<StatusBadge art="flaeche" status={f.status} className="text-[13px]" />}
      />

      <Karte>
        <Stepper art="flaeche" status={f.status} />
        <p className="mt-4 text-[14.5px] leading-relaxed text-ink-600">{statusInfo("flaeche", f.status).text}</p>
        {f.status === "abgelehnt" && f.ablehnGrund && <p className="mt-2 text-[14.5px] font-medium text-ink-800">Begründung: {f.ablehnGrund}</p>}
      </Karte>

      {pa && (
        <section aria-labelledby="pachtangebot" className="ov-noise relative overflow-hidden rounded-3xl bg-navy-950 p-6 text-white md:p-8">
          <div aria-hidden="true" className="absolute -right-20 -top-20 h-60 w-60 rounded-full bg-ov-500/30 blur-[90px]" />
          <div className="relative grid gap-6 md:grid-cols-[minmax(0,1fr)_auto] md:items-end">
            <div className="min-w-0">
              <p className="flex items-center gap-2 text-[12px] font-semibold uppercase tracking-[0.16em] text-ov-300">
                <FileSignature aria-hidden="true" className="h-4 w-4" /> Pachtangebot vom {datum(pa.am)}
              </p>
              <dl className="mt-4 grid gap-5 sm:grid-cols-3">
                <div>
                  <dt className="text-[12.5px] text-white/60">Pacht je Hektar und Jahr <Begriff id="flaechenpacht" nurIcon /></dt>
                  <dd className="ov-num mt-1 font-display text-[28px] font-extrabold">{eur(pa.euroProHaJahr)}</dd>
                </div>
                <div>
                  <dt className="text-[12.5px] text-white/60">Für Ihre {ha(f.ha)} pro Jahr</dt>
                  <dd className="ov-num mt-1 font-display text-[28px] font-extrabold">{f.ha ? eur(pa.euroProHaJahr * f.ha) : "–"}</dd>
                </div>
                <div>
                  <dt className="text-[12.5px] text-white/60">Laufzeit</dt>
                  <dd className="mt-1 font-display text-[22px] font-bold">{pa.laufzeitJahre} Jahre{pa.verlaengerung ? <span className="block text-[13px] font-normal text-white/60">{pa.verlaengerung}</span> : null}</dd>
                </div>
              </dl>
              {pa.text && <p className="mt-4 max-w-2xl whitespace-pre-line text-[14.5px] leading-relaxed text-white/75">{pa.text}</p>}
              <p className="mt-3 text-[12.5px] text-white/50">Zur Einordnung: übliche Pacht für Freiflächen-PV {eur(PACHT.freiflaecheProHa.min)}–{eur(PACHT.freiflaecheProHa.max)} je ha und Jahr (DACH). Verbindlich ist allein der Vertrag.</p>
            </div>
            {eigen && f.status === "pachtangebot" && (
              <div className="flex flex-col gap-2">
                <StatusAktionen art="flaeche" id={f.id} status={f.status} als="eigentuemer" />
                <Link href="#nachrichten" className="inline-flex items-center gap-2 text-[14px] font-semibold text-white/80 hover:text-white">
                  <MessageSquareText aria-hidden="true" className="h-4 w-4" /> Rückfrage stellen
                </Link>
              </div>
            )}
          </div>
        </section>
      )}

      <div className="grid gap-6 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
        <div className="min-w-0 space-y-6">
          {eigen && <KiFlaeche flaecheId={f.id} agri={!!f.agri} />}

          <Karte titel="Nachrichten" id="nachrichten" untertitel="Rückfragen und Abstimmung zu dieser Fläche">
            <NachrichtenThread bezugArt="flaeche" bezugId={f.id} nachrichten={thread.nachrichten} />
          </Karte>

          <Karte titel="Angaben zur Fläche">
            <Angaben
              items={[
                { label: "Bundesland / Kanton", wert: f.bundesland },
                { label: "Größe", wert: ha(f.ha) },
                { label: "Nutzung", wert: FLAECHE_NUTZUNG[f.nutzung] },
                { label: "Agri-PV gewünscht", wert: f.agri ? "Ja" : "Nein" },
                { label: "Flurstücke", wert: f.flurstuecke?.length ? f.flurstuecke.map((s) => [s.gemarkung, s.flur && `Flur ${s.flur}`, s.nummer && `Nr. ${s.nummer}`].filter(Boolean).join(" ")).join("; ") : "", breit: true },
                { label: "Hinweise", wert: f.hinweise, breit: true },
                { label: "Angelegt", wert: datumZeit(f.erstelltAm) },
                admin && f.eigentuemer ? { label: "Eigentümer (Konto)", wert: `${f.eigentuemer.vorname} ${f.eigentuemer.nachname} · ${f.eigentuemer.email}` } : null,
                admin && f.vorgangId ? { label: "Aus Anfrage", wert: <Link className="text-ov-700 underline" href={`/portal/admin/vorgaenge/${f.vorgangId}`}>{f.vorgangId}</Link> } : null,
              ]}
            />
            {bearbeitbar && (
              <details className="group mt-6 rounded-2xl bg-sand-50 ring-1 ring-ink-200/70" open={f.status === "entwurf" && eigen}>
                <summary className="cursor-pointer list-none px-4 py-3 text-[14.5px] font-semibold text-ov-700 [&::-webkit-details-marker]:hidden">
                  {f.status === "entwurf" ? "Angaben vervollständigen & einreichen" : "Angaben bearbeiten"}
                </summary>
                <div className="border-t border-ink-200/70 p-4 md:p-5">
                  <FlaecheFormular flaeche={f} />
                </div>
              </details>
            )}
          </Karte>
        </div>

        <div className="min-w-0 space-y-6">
          {(admin || eigen) && (
            <Karte titel={admin && !eigen ? "Bearbeitung (Backoffice)" : "Aktionen"}>
              {admin && (
                <div className="mb-5">
                  <Zuweisung art="flaeche" id={f.id} zustaendigId={f.zustaendigId} konten={adminKonten} />
                </div>
              )}
              {eigen && f.status === "pachtangebot" && <p className="text-[14px] leading-relaxed text-ink-600">Bitte prüfen Sie das Pachtangebot oben: annehmen oder Rückfrage per Nachricht stellen.</p>}
              {eigen && f.status !== "pachtangebot" && <StatusAktionen art="flaeche" id={f.id} status={f.status} als="eigentuemer" leerText={admin ? undefined : "Aktuell ist nichts von Ihnen zu tun – wir melden uns."} />}
              {admin && (
                <StatusAktionen
                  art="flaeche"
                  id={f.id}
                  status={f.status}
                  als="admin"
                  kontext={{ pachtVorschlag: { euroProHaJahr: f.agri ? PACHT.agriProHa.mittel : PACHT.freiflaecheProHa.mittel, laufzeitJahre: PACHT.laufzeit, verlaengerung: PACHT.verlaengerung } }}
                  leerText="Keine weiteren Schritte vorgesehen."
                />
              )}
              {!admin && f.zustaendig && <p className="mt-4 text-[13.5px] text-ink-500">Ihr Ansprechpartner: <span className="font-semibold text-ink-800">{f.zustaendig.vorname} {f.zustaendig.nachname}</span></p>}
            </Karte>
          )}

          <Karte titel="Verlauf">
            <Timeline art="flaeche" verlauf={f.statusVerlauf} />
          </Karte>

          {(admin || eigen) && (
            <Karte titel="Unterlagen zur Fläche" untertitel="Damit wir schnell und verbindlich prüfen können">
              <Checkliste checkliste={f.checkliste} bezugArt="flaeche" bezugId={f.id} kategorie="allgemein" kategorieJePunkt={{ flurkarte: "plan" }} darfHochladen={admin || eigen} />
            </Karte>
          )}

          <Karte titel="Dokumente" untertitel="Grundbuchauszug, Lageplan, Pachtangebot">
            <DokumentListe dokumente={dokumente} nutzerId={n.id} admin={admin} leerText="Noch keine Dokumente." />
            <div className="mt-4">
              <DokumentUpload bezugArt="flaeche" bezugId={f.id} kategorien={admin ? ["vertrag", "plan", "allgemein"] : ["allgemein", "plan"]} />
            </div>
          </Karte>

          {admin && <AufgabenKarte nutzer={n} bezugArt="flaeche" bezugId={f.id} />}
          {admin && <AktivitaetsFeed nutzer={n} objektId={f.id} weitereIds={f.vorgangId ? [f.vorgangId] : []} />}

          {f.agri && (
            <Hinweis ton="ok" titel="Agri-PV">
              Die landwirtschaftliche Nutzung bleibt Hauptnutzung. Wir planen nach DIN SPEC 91434 – Details stimmen wir mit Ihnen ab.
            </Hinweis>
          )}
        </div>
      </div>
    </div>
  );
}
import { ShieldCheck, Clock, Coins } from "lucide-react";
import FlaecheFormular from "@/components/Portal/FlaecheFormular";
import { Karte, SeitenKopf } from "@/components/Portal/ui";
import { portalNutzer } from "@/lib/plattform/server/seite";
import { PACHT, PROVISION } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

export const metadata = { title: "Fläche hinzufügen" };

export default async function FlaecheNeu() {
  const n = await portalNutzer({ rollen: ["flaeche", "landwirt"] });
