      passwortHash: eigentuemer.passwortHash,
      sitzungVersion: 0,
      aktiv: true,
      emailBestaetigt: true,
      erstelltAm: vorTagen(40),
      letzterLogin: null,
      suchprofil: null,
      demo: true,
    };
