		"schutz": bereich("schutz", lambda b: {
			"natura2000": _jnu(b.get("natura2000")),
			"nsg": _jnu(b.get("nsg")),
			"lsg": _jnu(b.get("lsg")),
			"wsg": v.auswahl(b.get("wsg"), WSG, ""),
