// node fa_shot.mjs
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";

const BASIS = "http://localhost:3100";
const PW = "Demo-2026!";

async function cookieFuer(email) {
  const r = await fetch(BASIS + "/api/auth/login", { method: "POST", headers: { "Content-Type": "application/json", Origin: BASIS }, body: JSON.stringify({ email, passwort: PW }) });
  const c = (r.headers.getSetCookie?.() || []).find((x) => /oi_sitzung=/.test(x));
  const [paar] = c.split(";");
  const [name, wert] = paar.split("=");
  return { name, value: wert, url: BASIS };
}

async function flaecheId(cookie, teil) {
  const r = await fetch(BASIS + "/api/portal/flaechen", { headers: { Cookie: `${cookie.name}=${cookie.value}` } });
  const j = await r.json();
  return j.flaechen.find((f) => f.bezeichnung.includes(teil))?.id;
}

const auftraege = [];
const fl = await cookieFuer("flaeche@example.com");
const lw = await cookieFuer("landwirt@example.com");
const ko = await cookieFuer("kommune@example.com");
const muehl = await flaecheId(fl, "Mühlweg");
const agri = await flaecheId(lw, "Schlag Nord");
auftraege.push(["fa_angebot", `/portal/flaechen/${muehl}`, fl, [1440, 390]]);
auftraege.push(["fa_agri", `/portal/flaechen/${agri}`, lw, [1440]]);
auftraege.push(["fa_neu", `/portal/flaechen/neu`, lw, [1440, 390]]);
auftraege.push(["fa_kommune", `/portal/kommune`, ko, [1440, 390]]);
auftraege.push(["fa_kommunen", `/kommunen`, null, [390], "#anfrage"]);

const b = await chromium.launch();
try {
  for (const [name, pfad, cookie, breiten, element] of auftraege) {
    for (const breite of breiten) {
      const ctx = await b.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 }, deviceScaleFactor: 1 });
      if (cookie) await ctx.addCookies([cookie]);
      const p = await ctx.newPage();
      const fehler = [];
      p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
      p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
      const r = await p.goto(BASIS + pfad, { waitUntil: "load", timeout: 180000 });
      await p.waitForTimeout(2500);
      try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1500 }); } catch {}
      // Fachformular: alle Bereiche aufklappen (Aufnahme der neuen Formularteile)
      if (name === "fa_neu") await p.evaluate(() => document.querySelectorAll("form details").forEach((d) => (d.open = true)));
      const ueberlauf = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      const datei = fileURLToPath(new URL(`./shots/${name}_${breite}.png`, import.meta.url));
      if (element) await p.locator(element).screenshot({ path: datei });
      else await p.screenshot({ path: datei, fullPage: true });
      console.log(r.status(), `${name}_${breite}.png`, `Überlauf ${ueberlauf}px`, fehler.length ? "\n  " + fehler.join("\n  ") : "");
      await ctx.close();
    }
  }
} finally {
  await b.close();
}

